class Solution:
    def findMin(self, nums: List[int]) -> int:
        l, r = 0, len(nums) - 1
        minVal = nums[0]
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] < minVal:
                minVal = min(minVal, nums[mid])
            else:
                if nums[l] <= nums[mid]:
                    # 有序
                    minVal = min(minVal, nums[l])
                    l = mid + 1
                else:
                    minVal = min(minVal, nums[mid + 1])
                    r = mid - 1
        return minVal
